// `npm run build:engine`: compile the Rust allocator (src/lib.rs, via medroute-wasm/) to
// WebAssembly and embed it in src/lib/solar-allocation/engine-binary.ts, which the Analyze route
// runs in-process. Run it after changing the Rust engine, and commit the regenerated file.
// Needs Rust (https://rustup.rs) with `rustup target add wasm32-unknown-unknown`.

import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const localCargo = join(homedir(), ".cargo", "bin", "cargo");
const cargo = existsSync(localCargo) ? localCargo : "cargo";
execFileSync(
  cargo,
  [
    "build",
    "--manifest-path",
    "medroute-wasm/Cargo.toml",
    "--target",
    "wasm32-unknown-unknown",
    "--release",
  ],
  { stdio: "inherit" },
);

const wasm = readFileSync("medroute-wasm/target/wasm32-unknown-unknown/release/medroute_wasm.wasm");
// Fail loudly if the engine ever starts needing host imports; the route provides none.
const imports = WebAssembly.Module.imports(new WebAssembly.Module(wasm));
if (imports.length) throw new Error(`Engine must not import anything: ${JSON.stringify(imports)}`);

const out = "src/lib/solar-allocation/engine-binary.ts";
writeFileSync(
  out,
  `// Generated by \`npm run build:engine\` from the Rust allocator (src/lib.rs). Do not edit.\n` +
    `// ${wasm.length} bytes of WebAssembly, base64-encoded.\n` +
    `export const ENGINE_WASM_BASE64 =\n  "${wasm.toString("base64")}";\n`,
);
console.log(`Embedded ${wasm.length} bytes of WebAssembly in ${out}.`);
